exercises.solution:
ssh anna@203.0.113.50 'sudo tee /etc/nginx/sites-available/sklep >/dev/null <<EOF
server {
    listen 80;
    listen [::]:80;
    server_name sklep.firma.example;
    location / { proxy_pass http://127.0.0.1:8080; }
}
EOF
sudo ln -sfn ../sites-available/sklep /etc/nginx/sites-enabled/sklep; sudo nginx -t && sudo systemctl reload nginx'

ssh anna@203.0.113.50 'sudo tee /etc/nginx/snippets/sklep-proxy.conf >/dev/null <<EOF
client_max_body_size 20m;
add_header Strict-Transport-Security "max-age=31536000" always;
add_header X-Content-Type-Options nosniff always;
location / {
    proxy_pass http://127.0.0.1:8080;
    proxy_set_header Host \$host;
    proxy_set_header X-Real-IP \$remote_addr;
    proxy_set_header X-Forwarded-For \$proxy_add_x_forwarded_for;
    proxy_set_header X-Forwarded-Proto \$scheme;
    proxy_connect_timeout 5s;
    proxy_read_timeout 60s;
}
EOF
sudo sed -i "/listen 443 ssl;/a \ \ \ \ include /etc/nginx/snippets/sklep-proxy.conf;" /etc/nginx/sites-available/sklep
sudo sed -i "0,/location \/ { proxy_pass http:\/\/127.0.0.1:8080; }/{/location \/ { proxy_pass http:\/\/127.0.0.1:8080; }/d}" /etc/nginx/sites-available/sklep
sudo nginx -t && sudo systemctl reload nginx'
